/*
 * Modified by Actuna Sp. z o.o.:
 *   #34: new module - the escaping of error texts that are shown as HTML (RED.notify, .html(),
 *   templates), moved from RED.deploy (#22, #30) so that the library, the palette, the projects
 *   and the version control do not depend on the deploy module
 * This notice is required by section 4(b) of the Apache License 2.0.
 */

/**
 * Error texts for the places that insert them as HTML (RED.notify renders its message as HTML).
 * Text that comes from a server response, a user or an exception is escaped; the text of the
 * message catalog is HTML and stays as it is. Loaded without a DOM, so it can be unit tested.
 * @namespace RED.errors
 */
RED.errors = (function() {

    /**
     * Escapes `& < > " '`, so the text is safe as the content of an element and of an attribute.
     * `null` and `undefined` give an empty text. Escape a value once, when it is put into HTML.
     * @param {*} value
     * @returns {String}
     */
    function escape(value) {
        if (value === undefined || value === null) {
            return "";
        }
        return String(value)
            .replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;")
            .replace(/"/g,"&quot;").replace(/'/g,"&#39;");
    }

    /**
     * The JSON body of an error response, or null when there is none (no body, not JSON, not an object).
     * @param {Object} xhr - the failed request
     * @returns {Object|null}
     */
    function parseResponse(xhr) {
        var body = xhr.responseJSON;
        if (body === undefined && xhr.responseText) {
            try {
                body = JSON.parse(xhr.responseText);
            } catch (parseError) {
                // not JSON (for example an error page of a proxy): no structured body
                return null;
            }
        }
        return (body && typeof body === "object" && !Array.isArray(body)) ? body : null;
    }

    /**
     * RED._ for a message with HTML in the catalog: the values taken from a response, from the
     * flows or from an exception are escaped, never inserted as HTML.
     * @param {String} key - the catalog key
     * @param {Object} [params] - the values of the message, all escaped
     * @returns {String}
     */
    function translateEscaped(key, params) {
        var safe = {};
        Object.keys(params || {}).forEach(function(name) {
            safe[name] = escape(params[name]);
        });
        return RED._(key, safe);
    }

    /**
     * The catalog message `messageKey` (with the `message` parameter) for a failed request, as HTML
     * that is safe to show in a notification: the `message` of a JSON error response, otherwise a
     * generic text with the HTTP status - always escaped, never the raw body of the response.
     * @param {String} messageKey
     * @param {Object} xhr - the failed request
     * @returns {String}
     */
    function translateResponse(messageKey, xhr) {
        var body = parseResponse(xhr);
        var text = body && typeof body.message === "string" && body.message
            ? body.message
            : RED._("deploy.errors.unexpected", { status: xhr.status });
        return translateEscaped(messageKey, { message: text });
    }

    /**
     * The catalog message `messageKey` (with the `message` parameter) for a caught error of the
     * editor, escaped. An error of the editor (`code` "NODE_RED") shows its message, any other
     * exception its `toString()`; both can contain text of the imported flow.
     * @param {String} messageKey
     * @param {Error} error
     * @returns {String}
     */
    function translateException(messageKey, error) {
        var text = (error && error.code === "NODE_RED") ? error.message : String(error);
        return translateEscaped(messageKey, { message: text });
    }

    return {
        escape: escape,
        parseResponse: parseResponse,
        translateEscaped: translateEscaped,
        translateResponse: translateResponse,
        translateException: translateException
    };
})();

if (typeof module !== "undefined" && module.exports) {
    module.exports = RED.errors;
}
